mapper.select:
SELECT t.transfer_no, MIN(t.from_company_id) AS from_company_id, MIN(ffrom.company_name) AS from_company_name, MIN(t.to_company_id) AS to_company_id, MIN(fto.company_name) AS to_company_name, MIN(t.transfer_type) AS transfer_type, COUNT(*) AS quantity, MIN(sc.spec_code) AS spec_code, MIN(sc.service_type) AS service_type, MIN(sc.duration_days) AS duration_days, MIN(t.reason) AS reason, MIN(t.operator_user_id) AS operator_user_id, MIN(t.operator_user_name) AS operator_user_name, MAX(t.created_at) AS created_at FROM service_code_transfer t LEFT JOIN service_code sc ON sc.id = t.service_code_id LEFT JOIN dealer_company ffrom ON ffrom.company_id = t.from_company_id LEFT JOIN dealer_company fto ON fto.company_id = t.to_company_id WHERE t.transfer_no = #{transferNo}
AND (t.from_company_id = #{scopeCompanyId} OR t.to_company_id = #{scopeCompanyId})
GROUP BY t.transfer_no
